    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="app"></div>

    <script>
      const featuredProducts = [
        {
          badge: "New",
          name: "Luma Task Lamp",
          description: "Dim-to-warm lighting with a weighted base and brushed brass arm.",
          price: "$128",
          meta: "Desk lighting · 12h runtime"
        },
        {
          badge: "Best seller",
          name: "Cedar Wool Throw",
          description: "Soft woven layers designed to add texture to living rooms and reading nooks.",
          price: "$89",
          meta: "Home textile · 5 colors"
        },
        {
          badge: "Editor pick",
          name: "Arc Stone Tray",
          description: "A sculptural catchall for keys, jewelry, and everyday carry essentials.",
          price: "$54",
          meta: "Hand-finished · Marble composite"
        }
      ];

      const deals = [
        {
          title: "Bundle the bedroom",
          text: "Save on coordinated bedding, lamps, and bedside storage when you shop the room.",
          value: "Up to 25% off"
        },
        {
          title: "Weekend refresh",
          text: "A limited drop of season-ready accents and tabletop pieces with free shipping over $75.",
          value: "Ends Sunday"
        },
        {
          title: "Member extra",
          text: "Logged-in shoppers get early access to new colorways and private markdowns.",
          value: "Members save 10%"
        }
      ];

      const stories = [
        {
          meta: "Editorial / Living room",
          title: "How to layer light for a calmer evening routine",
          text: "A quick guide to mixing task, ambient, and accent lighting without overcomplicating the room."
        },
        {
          meta: "Style notes / Texture",
          title: "Three ways to make neutrals feel richer",
          text: "Materials, contrast, and scale do the heavy lifting when you want a restrained palette to feel intentional."
        },
        {
          meta: "Buying guide / Essentials",
          title: "What to look for in everyday objects that last",
          text: "We break down finish quality, maintenance, and the details that separate staples from short-term fills."
        }
      ];

      const productCard = (product) => `
        <article class="section-card product-card">
          <div class="product-card__media" aria-hidden="true"></div>
          <div class="product-card__meta">
            <span class="badge">${product.badge}</span>
            <span>${product.meta}</span>
          </div>
          <div>
            <h3>${product.name}</h3>
            <p>${product.description}</p>
          </div>
          <div class="product-card__footer">
            <span class="price">${product.price}</span>
            <a class="card__link" href="#featured" aria-label="View details for ${product.name}">
              View details
            </a>
          </div>
        </article>
      `;

      const dealCard = () => `
        <article class="deal-card deal-card--feature">
          <span class="eyebrow">Limited offer</span>
          <h3>Designed to help you refresh an entire space with less guesswork.</h3>
          <p>
            Curated bundles pair bestselling essentials with complementary accents so you can move from idea to finished room faster.
          </p>
          <a class="deal-card__link" href="#deals">Explore all deals</a>
        </article>
      `;

      const dealList = () => `
        <article class="deal-card">
          <h3>Top promotions</h3>
          <ul class="deal-list">
            ${deals
              .map(
                (deal) => `
                  <li>
                    <div>
                      <strong>${deal.title}</strong>
                      <span>${deal.text}</span>
                    </div>
                    <span class="badge">${deal.value}</span>
                  </li>
                `
              )
              .join("")}
          </ul>
        </article>
      `;

      const storyCard = (story) => `
        <article class="story-card">
          <div class="story-card__media" aria-hidden="true"></div>
          <div class="story-card__body">
            <p class="story-card__meta">${story.meta}</p>
            <h3>${story.title}</h3>
            <p>${story.text}</p>
            <a class="card__link" href="#stories" aria-label="Read more about ${story.title}">
              Read article
            </a>
          </div>
        </article>
      `;

      const app = `
        <header class="topbar">
          <div class="shell topbar__inner">
            <a class="brand" href="#main" aria-label="Nox Atelier home">
              <span class="brand__mark" aria-hidden="true"></span>
              <span class="brand__copy">
                <span class="brand__eyebrow">Retail brand</span>
                <span class="brand__name">Nox Atelier</span>
              </span>
            </a>
            <nav aria-label="Primary">
              <ul class="nav">
                <li><a href="#featured">Featured</a></li>
                <li><a href="#deals">Deals</a></li>
                <li><a href="#stories">Editorial</a></li>
              </ul>
            </nav>
          </div>
        </header>

        <main id="main">
          <section class="hero">
            <div class="shell hero__grid">
              <div class="hero__panel">
                <p class="eyebrow">Curated for modern living</p>
                <h1>Bring a sharper look to everyday shopping.</h1>
                <p class="lede">
                  Discover polished home essentials, seasonal deals, and editorial ideas that help you shop with more confidence and less clutter.
                </p>
                <div class="hero__actions">
                  <a class="button button--primary" href="#featured">Shop featured products</a>
                  <a class="button button--secondary" href="#stories">Read the editorial</a>
                </div>

                <div class="hero__stats" aria-label="Store highlights">
                  <div class="stat">
                    <span class="stat__value">120+</span>
                    <span class="stat__label">curated products</span>
                  </div>
                  <div class="stat">
                    <span class="stat__value">48h</span>
                    <span class="stat__label">fast dispatch window</span>
                  </div>
                  <div class="stat">
                    <span class="stat__value">4.9/5</span>
                    <span class="stat__label">average customer rating</span>
                  </div>
                </div>
              </div>

              <aside class="hero__sidebar" aria-label="Featured spotlight">
                <article class="spotlight">
                  <span class="spotlight__tag">Spotlight</span>
                  <h2 class="spotlight__title">The midnight collection</h2>
                  <p class="spotlight__meta">
                    Deep tones, tactile finishes, and statement silhouettes built for a more dramatic home edit.
                  </p>
                </article>
                <article class="spotlight">
                  <span class="spotlight__tag">New arrival</span>
                  <h2 class="spotlight__title">Objects with a quieter footprint</h2>
                  <p class="spotlight__meta">
                    Materials sourced with longevity in mind, paired with packaging designed to reduce waste.
                  </p>
                </article>
              </aside>
            </div>
          </section>

          <section class="section" id="featured">
            <div class="shell">
              <div class="section__header">
                <div>
                  <p class="eyebrow">Featured products</p>
                  <h2 class="section__title">Pieces that anchor a room and still feel effortless.</h2>
                </div>
                <p>Shop the collection that mixes practical function with a refined dark aesthetic and tactile finishes.</p>
              </div>
              <div class="section-grid featured-grid">
                ${featuredProducts.map(productCard).join("")}
              </div>
            </div>
          </section>

          <section class="section" id="deals">
            <div class="shell">
              <div class="section__header">
                <div>
                  <p class="eyebrow">Deals</p>
                  <h2 class="section__title">Offers worth checking before you finish your cart.</h2>
                </div>
                <p>From room bundles to member savings, these promotions are set up to make the next purchase feel like a win.</p>
              </div>
              <div class="section-grid deals-grid">
                ${dealCard()}
                ${dealList()}
              </div>
            </div>
          </section>

          <section class="section" id="stories">
            <div class="shell">
              <div class="section__header">
                <div>
                  <p class="eyebrow">Editorial content</p>
                  <h2 class="section__title">Read, browse, and get a better sense of how each piece fits.</h2>
                </div>
                <p>Short-form guides and styling notes help turn product discovery into a more useful browsing session.</p>
              </div>
              <div class="section-grid story-grid">
                ${stories.map(storyCard).join("")}
              </div>
            </div>
          </section>
        </main>

        <footer>
          <div class="shell footer__inner">
            <p>&copy; 2026 Nox Atelier. Curated retail for home, work, and everything between.</p>
            <div class="footer__links" aria-label="Footer links">
              <a href="#featured">Featured</a>
              <a href="#deals">Deals</a>
              <a href="#stories">Editorial</a>
            </div>
          </div>
        </footer>
      `;

      document.getElementById("app").innerHTML = app;
    </script>
